import{_ as o}from"./chunks/commandify-icon.CZr-ODzb.js";import{_ as a,o as t,c as i,a2 as r}from"./chunks/framework.Crpw6aS5.js";const n="/assets/feature-graphic.BEOfQViT.png",s="/assets/01-screen.M465hyS5.png",l="/assets/02-screen.DmJs1wS0.png",d="/assets/03-screen.CZBUp80c.png",b=JSON.parse('{"title":"Commandify — Spotify Voice Control","description":"Archived notes on Commandify, a voice-controlled Spotify Android app (no longer available).","frontmatter":{"title":"Commandify — Spotify Voice Control","description":"Archived notes on Commandify, a voice-controlled Spotify Android app (no longer available)."},"headers":[],"relativePath":"software-engineering/android-app-development/commandify-spotify-voice-control.md","filePath":"software-engineering/android-app-development/commandify-spotify-voice-control.md"}'),p={name:"software-engineering/android-app-development/commandify-spotify-voice-control.md"};function c(m,e,f,y,h,u){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="commandify-—-spotify-voice-control" tabindex="-1">Commandify — Spotify Voice Control <a class="header-anchor" href="#commandify-—-spotify-voice-control" aria-label="Permalink to &quot;Commandify — Spotify Voice Control&quot;">​</a></h1><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><ul><li>Type: webpage + user notes</li><li>Origin: <a href="https://spotify-voice-control.en.aptoide.com/app" target="_blank" rel="noreferrer">Aptoide archive listing</a> (formerly on Google Play); developer notes from Devin Norgarb</li><li>Imported: 2026-07-31</li></ul><h2 id="content" tabindex="-1">Content <a class="header-anchor" href="#content" aria-label="Permalink to &quot;Content&quot;">​</a></h2><p><img src="'+o+'" alt="Commandify icon"></p><p><strong>Developer:</strong> Devin Norgarb · <strong>Category:</strong> Music &amp; Audio / Multimedia · <strong>Last known version:</strong> 6.4.0 (Oct 2021) · <strong>Reach:</strong> 5000+ users</p><blockquote><p><strong>No longer available.</strong> Commandify was pulled / stopped working after Spotify removed the ability for third-party developers to use the Spotify API in the way this app required. It is not offered on Google Play anymore and cannot be revived without Spotify restoring equivalent developer API access. At its peak it had <strong>over 5000+ users</strong>.</p></blockquote><h3 id="what-it-was" tabindex="-1">What it was <a class="header-anchor" href="#what-it-was" aria-label="Permalink to &quot;What it was&quot;">​</a></h3><p>By using voice prompts, Commandify let you control Spotify playback and library management hands-free — play songs and playlists, add tracks, find albums and artists, pull “Recently Recommended” tracks, and toggle media between Spotify-enabled devices.</p><p>The goal was full speech control of your Spotify account, devices, and library, with a UI for hands-on selection when you preferred tapping.</p><h3 id="voice-ui-features" tabindex="-1">Voice / UI features <a class="header-anchor" href="#voice-ui-features" aria-label="Permalink to &quot;Voice / UI features&quot;">​</a></h3><ul><li>Play / pause</li><li>Skip and rewind tracks</li><li>Play playlists; open a playlist</li><li>Control volume</li><li>Search genres, artists, and albums</li><li>Toggle playback between signed-in Spotify devices</li><li>Song suggestions and recommendations</li><li>Add songs to playlists; create playlists</li><li>Voice tab switching — Open Playlists, Open Recent Tracks, Open Recommended</li></ul><p>Example: <em>“Play Rock &#39;n Roll”</em>, <em>“Play Led Zeppelin”</em>, or <em>“Play Dark Side of the Moon Pink Floyd”</em> (no need for filler words like “artist” / “album”).</p><p>Active device showed green under <strong>Devices</strong>; playback routed to the selected Spotify Connect target (phone, Smart TV, etc.).</p><h3 id="requirements-when-it-worked" tabindex="-1">Requirements (when it worked) <a class="header-anchor" href="#requirements-when-it-worked" aria-label="Permalink to &quot;Requirements (when it worked)&quot;">​</a></h3><ul><li>Android 4.4+</li><li>Spotify Premium for most features (Spotify Web API / Connect constraints of the era)</li></ul><h3 id="figures" tabindex="-1">Figures <a class="header-anchor" href="#figures" aria-label="Permalink to &quot;Figures&quot;">​</a></h3><p><img src="'+n+'" alt="Commandify feature graphic"></p><p><img src="'+s+'" alt="Commandify — tap and speak / now playing"></p><p><img src="'+l+'" alt="Commandify screenshot"></p><p><img src="'+d+'" alt="Commandify screenshot"></p><h2 id="key-takeaways" tabindex="-1">Key Takeaways <a class="header-anchor" href="#key-takeaways" aria-label="Permalink to &quot;Key Takeaways&quot;">​</a></h2><ul><li>Commandify was a voice-first Spotify controller for Android with 5000+ users.</li><li>It is <strong>discontinued</strong>: Spotify removed the third-party API access the app depended on.</li><li>Historical listing/archive: <a href="https://spotify-voice-control.en.aptoide.com/app" target="_blank" rel="noreferrer">Aptoide — Commandify</a>.</li></ul>',23)])])}const k=a(p,[["render",c]]);export{b as __pageData,k as default};
